	sealed class Claset09bMessageProcessorTest : SGMessageProcessorTest
	{
		[ExpectNoExceptions]
		public void TestClaset09bMessageProcessor()
		{
			IncomingMessage.EM_MessageText = allCodesMsg;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
		}

		public void TestUpdateCountryCodes()
		{
			// Customs Common Code: CTYCODE
			var refCountryCount = Factory.GetDatabaseCount(typeof(RefCountry));
			IncomingMessage.EM_MessageText = cTYCODEMsg;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Country Code records should not be updated by this SG Customs Message / Process - maintenance of RefCountry file to remain with core processing.", refCountryCount, Factory.GetDatabaseCount(typeof(RefCountry)));
		}

		[ExpectNoExceptions]
		public void TestSameMsgVersion()
		{
			// Actual messages received from Customs but not processed
			IncomingMessage.EM_MessageText = clasetTxt1;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("Message should be processed", EDIMessage.Status.Received, IncomingMessage.EM_Status);
			IncomingMessage.EM_MessageText = clasetTxt2;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("Second CLASET Message in this set should also be processed", EDIMessage.Status.Received, IncomingMessage.EM_Status);
			IncomingMessage.EM_MessageText = clasetTxt3;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("Third CLASET Message, first in CPDCODE set should be processed", EDIMessage.Status.Received, IncomingMessage.EM_Status);
		}

		public void TestProcessSameRefMsgMultipleTimes()
		{
			IncomingMessage.EM_MessageText = clasetTxt1;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("Message should be processed", EDIMessage.Status.Received, IncomingMessage.EM_Status);
			IncomingMessage.EM_MessageText = clasetTxt2;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("Second CLASET Message in this set should also be processed", EDIMessage.Status.Received, IncomingMessage.EM_Status);
			var updatedHSCount = Factory.GetDatabaseCount(typeof(TariffView));
			IncomingMessage.EM_MessageText = clasetTxt1;
			MessageProcessor.ProcessMessage(IncomingMessage);
			Factory.Save();
			AssertEquals("Message Type should be REF", Claset09bMessageProcessor.MessageType, IncomingMessage.EM_MessageType);
			AssertEquals("First CLASET Message should be processed again without any issues", EDIMessage.Status.Received, IncomingMessage.EM_Status);
			AssertEquals("Processing the first file again should not affect the values already updated.", updatedHSCount, Factory.GetDatabaseCount(typeof(TariffView)));
		}

		public void TestForwardToRefDataRepo()
		{
			using (SGCustomsDataRegistry.Instance.SendTestMessages.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				IncomingMessage.EM_MessageText = "HELLO WORLD";
				MessageProcessor.ProcessMessage(IncomingMessage);
				AssertEquals(EDIMessage.Status.Failed, IncomingMessage.EM_Status);
				var query = new ZQuery(EDIInterchangeSchema.EI_ApplicationCode, EDIInterchangeTypeList.Codes.GenericMessageDelivery);
				query.FetchOnlyFromLocalCache = true;
				AssertNull(Factory.LoadTop1<EDIInterchange>(query));
				IncomingMessage.EM_Status = EDIMessage.Status.Queued;
				IncomingMessage.EM_MessageText = clasetTxt1;
				MessageProcessor.ProcessMessage(IncomingMessage);
				var interchange = Factory.LoadTop1<EDIInterchange>(query);
				RefDataRepoSenderTest.AssertInterchange(interchange, "CUSTOMS_DATA_REPO_TEST", "RDM", $@"<RefDbRepoMessage><Source>SG</Source><SubSource>CLASET</SubSource><ContentType>EDF</ContentType><Data>{System.Security.SecurityElement.Escape(clasetTxt1)}</Data></RefDbRepoMessage>");
			}
		}

